#!/usr/bin/env python3
"""
DSL Generator for 极限生存挑战 (Extreme Survival Challenge) Scratch Game
Generates canonical DSL v1.1 scripts for the survival game.
"""

import json
import os
from datetime import datetime

# Paths
BASE_DIR = "/Volumes/extern-1T-hardisk/workspace/01-repo/03-agents/Turbo-pi/packages/agent-server/eval/results/campaign-20260819/day3/experiment/task_00021_generate_canonical_dsl_v1_1_scripts_for_scratch_survival_game"
CONFIG_DIR = os.path.join(BASE_DIR, "config")
DOCS_DIR = os.path.join(BASE_DIR, "docs")
OUTPUT_DIR = os.path.join(BASE_DIR, "output")

# Load project metadata
with open(os.path.join(CONFIG_DIR, "project_metadata.json"), "r", encoding="utf-8") as f:
    metadata = json.load(f)

# Determine final values from all sources
# game_balance.yaml is FINAL approved v2.3
initial_lives = 5
initial_time = 30
initial_score = 0
status_values = ["准备", "进行中", "结束"]

# Difficulty tiers from notes (override with time condition)
difficulty_tiers = {
    "tier1": {"label": "Normal", "score_threshold": 0, "spawn_interval": 0.5},
    "tier2": {"label": "Hard", "score_threshold": 10, "spawn_interval": 0.4},
    "tier3": {"label": "Extreme", "score_threshold": 20, "spawn_interval": 0.3, "time_condition": ">5"}
}

# Sprites
sprites = metadata["sprites"]
stage = metadata["stage"]

# Broadcast names from metadata
broadcasts = metadata["broadcasts"]

def get_next_hat_id(sprite_name, prefix="hat_"):
    counter = getattr(difficulty_tiers, '_counter', {}).get(sprite_name, 0)
